<script>
function openEnquiryModal() {
    var m = document.getElementById("elementor-popup-modal-11717");
    if (m) m.classList.add("is-active");
}
function closeEnquiryModal() {
    var m = document.getElementById("elementor-popup-modal-11717");
    if (m) m.classList.remove("is-active");
}
document.addEventListener("DOMContentLoaded", function() {
    // Backdrop click close
    var m = document.getElementById("elementor-popup-modal-11717");
    if (m) {
        m.addEventListener("click", function(e) {
            if (e.target === m) closeEnquiryModal();
        });
    }
    // Mobile menu toggle & nested submenu accordion
    var toggles = document.querySelectorAll(".elementor-menu-toggle");
    var mobNav = document.querySelector("nav.elementor-nav-menu--dropdown");
    if (mobNav) {
        mobNav.querySelectorAll("li.menu-item-has-children").forEach(function(li) {
            var directLink = li.querySelector(":scope > a");
            var directSub = li.querySelector(":scope > ul.sub-menu");
            if (!directLink || !directSub || li.querySelector(":scope > .sd-mob-row")) return;
            var row = document.createElement("div");
            row.className = "sd-mob-row";
            li.insertBefore(row, directLink);
            row.appendChild(directLink);
            var subBtn = document.createElement("button");
            subBtn.type = "button";
            subBtn.className = "sd-mob-sub-toggle";
            subBtn.setAttribute("aria-label", "Toggle Submenu");
            subBtn.textContent = "+";
            row.appendChild(subBtn);
            function toggleSub(e) {
                e.preventDefault();
                e.stopPropagation();
                var opened = li.classList.toggle("sd-sub-open");
                subBtn.textContent = opened ? "−" : "+";
            }
            subBtn.addEventListener("click", toggleSub);
            if ((directLink.getAttribute("href") || "").trim() === "#") {
                directLink.addEventListener("click", toggleSub);
            }
        });
    }
    toggles.forEach(function(btn) {
        btn.addEventListener("click", function(e) {
            e.preventDefault();
            e.stopPropagation();
            if (!mobNav) return;
            var isOpen = mobNav.classList.toggle("sd-mobile-open");
            btn.classList.toggle("elementor-active", isOpen);
            btn.setAttribute("aria-expanded", isOpen ? "true" : "false");
            mobNav.setAttribute("aria-hidden", isOpen ? "false" : "true");
        });
    });
    document.addEventListener("click", function(e) {
        if (mobNav && mobNav.classList.contains("sd-mobile-open")) {
            var header = document.querySelector(".elementor-element-3397fd0b");
            if (header && !header.contains(e.target)) {
                mobNav.classList.remove("sd-mobile-open");
                toggles.forEach(function(b) {
                    b.classList.remove("elementor-active");
                    b.setAttribute("aria-expanded", "false");
                });
            }
        }
    });

    // Desktop Navigation Graceful Hover Intent & Delay Controller
    var menuItemsWithChildren = document.querySelectorAll(".elementor-nav-menu--main li.menu-item-has-children");
    menuItemsWithChildren.forEach(function(item) {
        var hideTimeout = null;

        item.addEventListener("mouseenter", function() {
            if (hideTimeout) {
                clearTimeout(hideTimeout);
                hideTimeout = null;
            }
            // Close unrelated sibling submenus
            var parentUl = item.closest("ul");
            if (parentUl) {
                Array.from(parentUl.children).forEach(function(sib) {
                    if (sib !== item && sib.classList.contains("menu-item-hovered")) {
                        sib.classList.remove("menu-item-hovered");
                    }
                });
            }
            item.classList.add("menu-item-hovered");
        });

        item.addEventListener("mouseleave", function() {
            hideTimeout = setTimeout(function() {
                item.classList.remove("menu-item-hovered");
            }, 300);
        });
    });

    // Also close flyout if hovering over a sibling leaf item (e.g. F D & C COLOURS)
    document.querySelectorAll(".elementor-nav-menu--main li:not(.menu-item-has-children)").forEach(function(leafItem) {
        leafItem.addEventListener("mouseenter", function() {
            var parentUl = leafItem.closest("ul");
            if (parentUl) {
                Array.from(parentUl.children).forEach(function(sib) {
                    if (sib.classList.contains("menu-item-hovered")) {
                        sib.classList.remove("menu-item-hovered");
                    }
                });
            }
        });
    });
    // Fallback swiper initialization for hero slider if needed
    if (typeof Swiper !== "undefined") {
        new Swiper(".elementor-slides-wrapper.swiper-container", {
            loop: true,
            autoplay: { delay: 5000, disableOnInteraction: false },
            effect: "fade",
            fadeEffect: { crossFade: true },
            speed: 600,
            navigation: {
                nextEl: ".elementor-swiper-button-next",
                prevEl: ".elementor-swiper-button-prev"
            },
            pagination: {
                el: ".swiper-pagination",
                clickable: true
            }
        });
    }
    // Testimonials slick carousel fallback
    if (typeof jQuery !== "undefined" && typeof jQuery.fn.slick !== "undefined") {
        jQuery(".pp-testimonials.pp-slick-slider").each(function() {
            if (!jQuery(this).hasClass("slick-initialized")) {
                jQuery(this).slick({
                    slidesToShow: 3,
                    slidesToScroll: 1,
                    autoplay: true,
                    autoplaySpeed: 3000,
                    speed: 600,
                    dots: true,
                    arrows: false,
                    responsive: [
                        { breakpoint: 1025, settings: { slidesToShow: 2, slidesToScroll: 1 } },
                        { breakpoint: 768, settings: { slidesToShow: 1, slidesToScroll: 1 } }
                    ]
                });
            }
        });
    }
});
</script>

